/**
 * seed.js — Carga inicial del mazo completo en Firestore
 *
 * Uso:
 *   node seed.js
 *
 * Requisitos:
 *   1. Tener firebase-admin instalado: npm install firebase-admin
 *   2. Descargar la Service Account Key desde Firebase Console
 *      → Project Settings → Service accounts → Generate new private key
 *      → Guardar como serviceAccountKey.json en este mismo directorio
 *   3. Nunca commitear serviceAccountKey.json al repositorio
 *
 * Qué hace:
 *   - Crea los 3 documentos raíz en `decks/` (coqueteo, sensaciones, intimidad)
 *   - Carga todas las cartas activas en la subcolección `decks/{deckId}/cards/`
 *   - Usa batch writes para eficiencia (máx 500 ops por batch)
 *   - Es idempotente: si ya existe una carta con el mismo ID, la actualiza
 */

const admin = require("firebase-admin");
const serviceAccount = require("./serviceAccountKey.json");

admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
});

const db = admin.firestore();
const { Timestamp, FieldValue } = admin.firestore;

