// ============================================================
// FUNCIÓN PRINCIPAL DE SEED
// ============================================================

async function seedDecks() {
  console.log("🌱 Iniciando seed del mazo en Firestore...\n");

  // Agrupar cartas por deckId
  const cardsByDeck = ALL_CARDS.reduce((acc, card) => {
    if (!acc[card.deckId]) acc[card.deckId] = [];
    acc[card.deckId].push(card);
    return acc;
  }, {});

  // Actualizar contadores en metadata
  for (const deckId of Object.keys(DECK_METADATA)) {
    DECK_METADATA[deckId].cardCount = (cardsByDeck[deckId] || []).length;
  }

  // Procesar cada deck
  for (const [deckId, metadata] of Object.entries(DECK_METADATA)) {
    console.log(`📦 Procesando deck: ${deckId} (${metadata.cardCount} cartas)`);

    // Crear/actualizar documento raíz del deck
    const deckRef = db.collection("decks").doc(deckId);
    await deckRef.set(metadata, { merge: true });

    // Cargar cartas en batches de 400 (límite Firestore = 500)
    const cards = cardsByDeck[deckId] || [];
    const BATCH_SIZE = 400;

    for (let i = 0; i < cards.length; i += BATCH_SIZE) {
      const batch = db.batch();
      const chunk = cards.slice(i, i + BATCH_SIZE);

      for (const card of chunk) {
        const cardDocId = String(card.id).padStart(3, "0");
        const cardRef = deckRef.collection("cards").doc(cardDocId);
        batch.set(
          cardRef,
          {
            ...card,
            active: true,
            createdAt: NOW,
            updatedAt: NOW,
            // Eliminar campos null para Firestore
            ...(card.groupDesc === null ? { groupDesc: FieldValue.delete() } : {}),
          },
          { merge: true }
        );
      }

      await batch.commit();
      console.log(
        `  ✅ Batch ${Math.floor(i / BATCH_SIZE) + 1}: ${chunk.length} cartas cargadas`
      );
    }

    console.log(`  ✔️  Deck '${deckId}' completado\n`);
  }

  console.log("🎉 Seed completado exitosamente.");
  console.log(`   Total cartas cargadas: ${ALL_CARDS.length}`);
  console.log(`   Decks: coqueteo (${cardsByDeck.coqueteo?.length}), sensaciones (${cardsByDeck.sensaciones?.length}), intimidad (${cardsByDeck.intimidad?.length})`);
  process.exit(0);
}

seedDecks().catch((error) => {
  console.error("❌ Error durante el seed:", error);
  process.exit(1);
});
